public static class ScenarioTests {
 static int checks;static void Check(bool good,string name){checks++;if(!good)throw new Exception(name);}static void Reject(Action test,string name){bool rejected=false;try{test();}catch(InvalidDataException){rejected=true;}Check(rejected,name);}
 static Dictionary<string,object> Obj(params object[] fields){var d=new Dictionary<string,object>();for(int i=0;i<fields.Length;i+=2)d[(string)fields[i]]=fields[i+1];return d;}
 public static Dictionary<string,object> FakeHeadset(){return Obj("deviceId","hid-0000000000000001","model","ROG DELTA II-KJP","online",true,"readbackConfirmed",true,"setCapabilities",ScenarioRules.HeadsetSettings.Where(s=>s!="lightingEffect"&&s!="lightingColor").ToArray(),"snapshot",Obj("eqLevels",new int[]{50,50,50,50,50,50,50,50},"eqEnabled",false,"noiseReductionRaw",1,"noiseReductionEnabled",true,"sideToneLevel",7,"sideToneEnabled",true,"voicePrompt",2,"latencyMs",60,"sleepMinutes",0,"lowBatteryThreshold",20,"lowBatteryVoicePrompt",true,"brightnessRaw",100,"lightingEffectCode",0,"color",new int[]{100,50,25},"lightingEnabled",true,"auraEnabled",false));}
 static Dictionary<string,object> FakeMouse(int rate,bool sync,params string[] capabilities){return Obj("deviceId","hid-0000000000000002","model","合成鼠标","online",true,"readbackConfirmed",true,"setCapabilities",capabilities,"snapshot",Obj("pollingRate",rate,"motionSync",sync,"sleepMinutes",3,"angleSnapping",false,"activeDpiStage",3,"dpiStages",new[]{400,800,1600,3200},"dpiStagesY",new[]{400,800,1600,3200}));}
 static ScenarioProfile Profile(){string warning;return new ScenarioProfile{Name="耳机情境 · 合成数据",Devices=new List<ScenarioDeviceProfile>{ScenarioRules.Capture("headset",FakeHeadset(),out warning)}};}
 public static void Main(){Run().GetAwaiter().GetResult();Console.WriteLine("Scenario profiles: "+checks+" checks passed. Fake delegates only; no worker, hardware, audio, process, macro or hook access.");}
 static async Task Run(){var profile=Profile();Check(profile.Devices[0].Settings.Count==14,"captures real-capability 14 fields");Check(profile.Devices[0].Settings.First(s=>s.Setting=="brightness").Value.Equals(100),"brightnessRaw getter mapping");Check(!profile.Devices[0].Settings.Any(s=>s.Setting=="lightingEffect"||s.Setting=="lightingColor"),"unknown mode not fabricated");
  var encoded=ScenarioRepository.Encode(profile);var loaded=ScenarioRepository.Decode(encoded);Check(loaded.Devices[0].Settings.Count==14,"round trip");var plan=ScenarioRules.BuildPlan(profile);Check(plan.Count==14,"14 commands");loaded.Devices[0].Settings[0].Value=new int[]{0,0,0,0,0,0,0,0};Check(((int[])profile.Devices[0].Settings[0].Value)[0]==50,"deep copy");
  var noLighting=ScenarioRepository.CloneRaw(profile);noLighting.Devices[0].IncludeLighting=false;Check(ScenarioRules.BuildPlan(noLighting).Count==11,"lighting filter only three confirmed fields");noLighting.Devices[0].Enabled=false;Check(ScenarioRules.BuildPlan(noLighting).Count==0,"disabled device no commands");
  var offline=FakeHeadset();offline["online"]=false;Reject(()=>{string w;ScenarioRules.Capture("headset",offline,out w);},"offline cannot capture");var unconfirmed=FakeHeadset();unconfirmed["readbackConfirmed"]=false;Reject(()=>{string w;ScenarioRules.Capture("headset",unconfirmed,out w);},"unconfirmed cannot capture");
  var mapped=FakeHeadset();mapped["setCapabilities"]=ScenarioRules.HeadsetSettings;mapped["snapshot"]=Obj("lightingEffectCode",2,"color",new int[]{12,34,56},"brightnessRaw",55);string warning;var light=ScenarioRules.Capture("headset",mapped,out warning);Check(light.Settings.Count==3,"missing scalar fields skipped");Check((int)light.Settings.First(s=>s.Setting=="lightingEffect").Value==2,"effect getter");Check(((int[])light.Settings.First(s=>s.Setting=="lightingColor").Value).SequenceEqual(new[]{12,34,56}),"color getter");Check(warning!=null,"capture reports missing fields");
  foreach(var bad in new object[]{null,"50",true,-1,101,50.5,Double.NaN,Double.PositiveInfinity})Reject(()=>ScenarioRules.CanonicalValue("headset","brightness",bad),"invalid brightness");Reject(()=>ScenarioRules.CanonicalValue("headset","brightness",52),"brightness step");Reject(()=>ScenarioRules.CanonicalValue("headset","latencyMs",50),"latency choices");Reject(()=>ScenarioRules.CanonicalValue("headset","sleepMinutes",1),"headset sleep choices");Reject(()=>ScenarioRules.CanonicalValue("keyboard","pollingRate",125),"keyboard polling");Reject(()=>ScenarioRules.CanonicalValue("headset","noiseReductionEnabled",1),"boolean type");Reject(()=>ScenarioRules.CanonicalValue("headset","eqLevels",new int[10]),"EQ count");Reject(()=>ScenarioRules.CanonicalValue("headset","lightingColor",new[]{256,0,0}),"RGB range");Reject(()=>ScenarioRules.CanonicalValue("headset","flashFirmware",1),"unknown setting");
  foreach(var mutate in new Action<ScenarioProfile>[] {p=>p.Version=2,p=>p.Name="",p=>p.Name=new string('x',121),p=>p.Id="../../bad",p=>p.Devices.Add(p.Devices[0]),p=>p.Devices[0].Settings.Add(p.Devices[0].Settings[0]),p=>p.Devices[0].Settings[13].Value="false",p=>p.Applications.Add(new ScenarioApplication{Name="Bad",Executable="C:relative.exe"})}){var invalid=ScenarioRepository.CloneRaw(profile);mutate(invalid);Reject(()=>ScenarioRules.Validate(invalid),"invalid profile");}
  var audio=ScenarioRules.CaptureAudio(Obj("flow","capture","endpointId","exact-mic-id","name","Microphone (ROG DELTA II-KJP)","active",true,"matchConfirmed",true,"readbackConfirmed",true,"volumePercent",45.1,"muted",false));Check(audio.Volume==45&&audio.ObservedVolumePercent==45.1,"audio observed and whole-percent target");profile.Audio.Add(audio);Check(ScenarioRules.BuildPlan(profile).Count==16,"audio two exact target commands");var audioPlan=ScenarioRules.BuildPlan(profile).Where(c=>c.Source=="audio").ToList();Check(audioPlan.All(c=>c.DeviceId=="exact-mic-id"&&c.Flow=="capture"),"no default endpoint target");var json=ScenarioRepository.Encode(profile);Reject(()=>ScenarioRepository.Decode(json.Replace("\"Volume\":45","\"Volume\":45.5")),"raw fractional volume rejected before typed deserialization");Reject(()=>ScenarioRepository.Decode(json.Replace("\"Volume\":45,","")),"missing audio volume rejected");Reject(()=>ScenarioRepository.Decode(json.Replace("\"Muted\":false","\"Muted\":\"false\"")),"raw mute type");Reject(()=>ScenarioRepository.Decode(json.Replace("\"IncludeLighting\":true,","")),"missing lighting inclusion rejected");Reject(()=>ScenarioRepository.Decode("null"),"null document");Reject(()=>ScenarioRepository.Decode("{"),"malformed document");
  var duplicate=ScenarioRepository.CloneRaw(profile);duplicate.Audio.Add(new ScenarioAudioProfile{Flow="render",EndpointId="exact-mic-id",Name="Wrong duplicate",Volume=45,ObservedVolumePercent=45.1});Reject(()=>ScenarioRules.Validate(duplicate),"same endpoint cannot bind both directions");
  var mouse=new ScenarioDeviceProfile{Kind="mouse",DeviceId="mouse-id",Name="Mouse",Settings=new List<ScenarioSetting>{new ScenarioSetting{Setting="pollingRate",Value=8000},new ScenarioSetting{Setting="motionSync",Value=true}}};Reject(()=>ScenarioRules.Validate(new ScenarioProfile{Devices=new List<ScenarioDeviceProfile>{mouse}}),"cross-field motion sync conflict");mouse.Settings[1].Value=false;var mousePlan=ScenarioRules.BuildPlan(new ScenarioProfile{Devices=new List<ScenarioDeviceProfile>{mouse}});Check(mousePlan[0].Setting=="motionSync","disable sync before raising rate");mouse.Settings[0].Value=1000;mouse.Settings[1].Value=true;mousePlan=ScenarioRules.BuildPlan(new ScenarioProfile{Devices=new List<ScenarioDeviceProfile>{mouse}});Check(mousePlan.Last().Setting=="motionSync","lower rate before enable sync");
  var conflictState=FakeMouse(8000,true,ScenarioRules.MouseSettings);var originalState=new JavaScriptSerializer().Serialize(conflictState);var capturedMouse=ScenarioRules.Capture("mouse",conflictState,out warning);Check(!capturedMouse.Settings.Any(s=>s.Setting=="pollingRate"||s.Setting=="motionSync"),"capture omits both unsafe mouse fields");Check(capturedMouse.Settings.Count==7&&capturedMouse.Settings.Count(s=>s.Setting=="dpiStage")==4&&capturedMouse.Settings.Any(s=>s.Setting=="sleepMinutes"),"unsafe pair does not discard remaining confirmed mouse fields");Check(warning!=null&&warning.Contains("8000 Hz")&&warning.Contains("Motion Sync")&&warning.Contains("同时跳过"),"unsafe capture explains why both fields were skipped");Check(new JavaScriptSerializer().Serialize(conflictState)==originalState,"capture never changes raw snapshot or capabilities");var capturedPlan=ScenarioRules.BuildPlan(new ScenarioProfile{Devices=new List<ScenarioDeviceProfile>{capturedMouse}});Check(capturedPlan.Count==7&&!capturedPlan.Any(c=>c.Setting=="pollingRate"||c.Setting=="motionSync"),"captured plan cannot trigger either unsupported transition");
  foreach(var legalState in new[]{FakeMouse(8000,false,"pollingRate","motionSync","sleepMinutes"),FakeMouse(1000,true,"pollingRate","motionSync","sleepMinutes")}){var legalMouse=ScenarioRules.Capture("mouse",legalState,out warning);var legalSnapshot=(IDictionary<string,object>)legalState["snapshot"];Check(warning==null&&legalMouse.Settings.Count==3&&legalMouse.Settings.First(s=>s.Setting=="pollingRate").Value.Equals(legalSnapshot["pollingRate"])&&legalMouse.Settings.First(s=>s.Setting=="motionSync").Value.Equals(legalSnapshot["motionSync"]),"legal mouse pair is preserved during capture");}
  foreach(string one in new[]{"pollingRate","motionSync"}){var oneState=FakeMouse(8000,true,one,"sleepMinutes","dpiStage");var oneMouse=ScenarioRules.Capture("mouse",oneState,out warning);Check(oneMouse.Settings.Count==5&&!oneMouse.Settings.Any(s=>s.Setting=="pollingRate"||s.Setting=="motionSync")&&warning!=null,"unsafe snapshot skips a field even when its counterpart is not a setter capability");Reject(()=>{string w;ScenarioRules.Capture("mouse",FakeMouse(8000,true,one),out w);},"only unsupported captured field cannot form empty profile");}
  Reject(()=>{string w;ScenarioRules.Capture("mouse",FakeMouse(8000,true,"pollingRate","motionSync"),out w);},"unsafe pair alone cannot form empty profile");
  var onlyRate=ScenarioRules.Capture("mouse",FakeMouse(8000,false,"pollingRate"),out warning);Check(onlyRate.Settings.Count==1&&onlyRate.Settings[0].Setting=="pollingRate"&&warning==null,"legal 8K with false sync is retained when only rate is a setter");var onlySync=ScenarioRules.Capture("mouse",FakeMouse(1000,true,"motionSync"),out warning);Check(onlySync.Settings.Count==1&&onlySync.Settings[0].Setting=="motionSync"&&warning==null,"legal lower rate with true sync is retained when only sync is a setter");
  int reads=0,sends=0;Func<List<ScenarioCommand>,CancellationToken,Task> before=(p,t)=>{reads++;return Task.FromResult(0);};Func<ScenarioCommand,Task<ScenarioApplyResult>> send=c=>{sends++;return Task.FromResult(new ScenarioApplyResult{Outcome="confirmed",Message="Fake confirmed"});};var broken=ScenarioRepository.CloneRaw(profile);broken.Devices[0].Settings.Last().Value="bad";bool rejected=false;try{await ScenarioExecutor.RunAsync(broken,before,send,CancellationToken.None);}catch(InvalidDataException){rejected=true;}Check(rejected&&reads==0&&sends==0,"last invalid setting rejected before first read/write");
  rejected=false;try{await ScenarioExecutor.RunAsync(profile,(p,t)=>{throw new IOException("Fake device offline");},send,CancellationToken.None);}catch(IOException){rejected=true;}Check(rejected&&sends==0,"failed all-target preflight sends nothing");
  sends=0;var results=await ScenarioExecutor.RunAsync(profile,before,c=>{sends++;if(sends==2)throw new IOException("Fake second setting failure");return Task.FromResult(new ScenarioApplyResult{Outcome=sends==3?"unconfirmed":"confirmed",Message="Fake result"});},CancellationToken.None);Check(sends==16&&results.Count==16,"continue partial failures no rollback");Check(results.Count(r=>r.Outcome=="failed")==1&&results.Count(r=>r.Outcome=="unconfirmed")==1&&results.Count(r=>r.Confirmed)==14,"per-setting outcomes");
  sends=0;using(var cancel=new CancellationTokenSource()){results=await ScenarioExecutor.RunAsync(profile,before,c=>{sends++;if(sends==1)cancel.Cancel();return Task.FromResult(new ScenarioApplyResult{Outcome="confirmed",Message="Fake result"});},cancel.Token);Check(sends==1&&results.Count(r=>r.Outcome=="cancelled")==15,"cancel stops remaining writes");}
  var folder=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"scenario-test-data",Guid.NewGuid().ToString("N"));var repository=new ScenarioRepository(folder);repository.Save(profile);profile.Name="Updated";repository.Save(profile);string file=Directory.GetFiles(folder,"*.rogscenario.json").Single();Check(ScenarioRepository.Read(file).Name=="Updated","atomic save overwrite");Check(Directory.GetFiles(folder,"*.tmp").Length==0,"own temporary cleaned");string repositoryWarning;Check(repository.List(out repositoryWarning).Count==1&&repositoryWarning==null,"local list");File.WriteAllText(Path.Combine(folder,"bad.rogscenario.json"),"null");Check(repository.List(out repositoryWarning).Count==1&&repositoryWarning!=null&&File.Exists(Path.Combine(folder,"bad.rogscenario.json")),"broken local file preserved");
 }
